```ts
type KnowledgePlan = {
  mode: "skip" | "fts" | "hybrid";
  tokenBudget: number; // cứng, đếm bằng chars/4
  kinds: EpisodeKind[]; // thứ tự ưu tiên
  maxCards: number;
  minScore: number;
  timeoutMs: { embed: number; db: number };
